from __future__ import annotations

"""Calendar primitives for the Excel 1900 date system.

Reports built in Excel store dates as integer "serial numbers": serial 1 is the
first day of the calendar, and each later day is the next integer. The 1900 date
system has a well-known quirk that any tool reading or writing these serials has
to live with, so the helpers here are written against that system rather than the
plain proleptic Gregorian calendar.

Reference anchors a correct conversion has to honor:

    serial 1  -> 1900-01-01
    serial 59 -> 1900-02-28
    serial 61 -> 1900-03-01

Serial 60 sits between 59 and 61. In the 1900 date system it does not point at a
real calendar date; downstream code treats it as a value that must be rejected.
"""

from dataclasses import dataclass

# The 1900 date system counts forward from this day as serial 1.
EPOCH_YEAR = 1900
EPOCH_MONTH = 1
EPOCH_DAY = 1

# The reserved serial that has no real calendar date in this system.
RESERVED_SERIAL = 60

_DAYS_IN_MONTH = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)

_MONTH_NAMES = (
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December",
)


def is_leap_year(year: int) -> bool:
    """Standard Gregorian leap-year test."""

    if year % 4 != 0:
        return False
    if year % 100 != 0:
        return True
    return year % 400 == 0


def days_in_month(year: int, month: int) -> int:
    if month < 1 or month > 12:
        raise ValueError(f"month out of range: {month}")
    if month == 2 and is_leap_year(year):
        return 29
    return _DAYS_IN_MONTH[month - 1]


def month_name(month: int) -> str:
    if month < 1 or month > 12:
        raise ValueError(f"month out of range: {month}")
    return _MONTH_NAMES[month - 1]


@dataclass(frozen=True)
class CalendarDate:
    """A plain calendar date used by the report exporter."""

    year: int
    month: int
    day: int

    def __post_init__(self) -> None:
        if self.year < EPOCH_YEAR:
            raise ValueError(f"year before the epoch is not supported: {self.year}")
        if self.month < 1 or self.month > 12:
            raise ValueError(f"month out of range: {self.month}")
        max_day = days_in_month(self.year, self.month)
        if self.day < 1 or self.day > max_day:
            raise ValueError(f"day out of range for {self.year}-{self.month:02d}: {self.day}")

    def iso(self) -> str:
        return f"{self.year:04d}-{self.month:02d}-{self.day:02d}"

    def pretty(self) -> str:
        return f"{month_name(self.month)} {self.day}, {self.year}"

    def as_tuple(self) -> tuple[int, int, int]:
        return (self.year, self.month, self.day)


def days_before_year(year: int) -> int:
    """Number of real calendar days from the epoch year up to Jan 1 of ``year``."""

    total = 0
    for y in range(EPOCH_YEAR, year):
        total += 366 if is_leap_year(y) else 365
    return total


def days_before_month(year: int, month: int) -> int:
    """Number of days from Jan 1 of ``year`` up to the first of ``month``."""

    total = 0
    for m in range(1, month):
        total += days_in_month(year, m)
    return total


def ordinal_from_epoch(date: CalendarDate) -> int:
    """Count of days from 1900-01-01 (which is day 0) to ``date``.

    This is a pure calendar count with no date-system adjustment applied.
    """

    return (
        days_before_year(date.year)
        + days_before_month(date.year, date.month)
        + (date.day - 1)
    )

