import pytest

from excel_calendar import CalendarDate, RESERVED_SERIAL
from excel_serial import (
    date_to_serial,
    round_trip_date,
    round_trip_serial,
    serial_to_date,
    shift_serial,
)


def D(y, m, d):
    return CalendarDate(year=y, month=m, day=d)


# --- happy path: a serial well past the leap boundary -----------------------

def test_known_serial_maps_to_expected_date():
    # A widely cited reference value in the 1900 date system.
    assert serial_to_date(40000).iso() == "2009-07-06"


def test_known_date_maps_to_expected_serial():
    assert date_to_serial(D(2009, 7, 6)) == 40000


# --- anchors that pin the calendar to the 1900 date system ------------------

def test_epoch_anchor():
    assert serial_to_date(1).iso() == "1900-01-01"
    assert date_to_serial(D(1900, 1, 1)) == 1


def test_serial_59_is_feb_28():
    assert serial_to_date(59).iso() == "1900-02-28"
    assert date_to_serial(D(1900, 2, 28)) == 59


# --- boundary across the phantom leap day -----------------------------------

def test_serial_61_is_march_first():
    # The day after Feb 28 1900 is serial 61, not 60, in this date system.
    assert serial_to_date(61).iso() == "1900-03-01"


def test_march_first_1900_maps_to_serial_61():
    assert date_to_serial(D(1900, 3, 1)) == 61


def test_feb_28_and_march_1_serials_differ_by_two():
    # Serial 60 is reserved, so the gap across the boundary is two, not one.
    assert date_to_serial(D(1900, 3, 1)) - date_to_serial(D(1900, 2, 28)) == 2


# --- invalid / unexpected input ---------------------------------------------

def test_reserved_serial_is_rejected():
    with pytest.raises(ValueError):
        serial_to_date(RESERVED_SERIAL)


def test_serial_below_minimum_is_rejected():
    with pytest.raises(ValueError):
        serial_to_date(0)


def test_boolean_serial_is_rejected():
    with pytest.raises(TypeError):
        serial_to_date(True)


# --- round trips: the regression that the bug breaks ------------------------

@pytest.mark.parametrize("serial", [1, 2, 59, 61, 62, 100, 1000, 40000, 50000])
def test_serial_round_trip_is_identity(serial):
    assert round_trip_serial(serial) == serial


@pytest.mark.parametrize(
    "date",
    [
        (1900, 1, 1),
        (1900, 2, 28),
        (1900, 3, 1),
        (1901, 1, 1),
        (1999, 12, 31),
        (2000, 2, 29),
        (2020, 6, 15),
    ],
)
def test_date_round_trip_is_identity(date):
    d = D(*date)
    assert round_trip_date(d).as_tuple() == d.as_tuple()


# --- helper behavior built on top of the conversion -------------------------

def test_shift_across_boundary_skips_reserved_serial():
    # Feb 28 1900 (serial 59) plus one day is March 1 (serial 61).
    assert shift_serial(59, 2) == 61
    assert serial_to_date(shift_serial(59, 2)).iso() == "1900-03-01"


def test_modern_dates_unaffected_by_offset_consistency():
    # Two consecutive days in a modern year stay one serial apart.
    a = date_to_serial(D(2023, 3, 14))
    b = date_to_serial(D(2023, 3, 15))
    assert b - a == 1
    assert serial_to_date(b).iso() == "2023-03-15"
